14	    /**
15	     * Returns the index of {@code target} in a sorted array, or {@link #NOT_FOUND} when absent.
16	     *
17	     * @throws NullPointerException when {@code numbers} is null
18	     */
19	    public static int binarySearch(int[] numbers, int target) {
20	        Objects.requireNonNull(numbers, "numbers");
21	
22	        int low = 0;
23	        int high = numbers.length - 1;
24	
25	        while (low <= high) {
26	            final int mid = low + (high - low) / 2;
27	
28	            if (numbers[mid] == target) {
29	                return mid;
30	            }
31	
32	            if (numbers[mid] < target) {
33	                low = mid + 1;
34	            } else {
35	                high = mid - 1;
36	            }
37	        }
38	
39	        return NOT_FOUND;
40	    }
41	
